from __future__ import annotations
import math
from functools import reduce


def lcm_upto(n: int) -> int:
    return reduce(lambda a, b: a * b // math.gcd(a, b), range(1, n + 1), 1)


def divisor_property_certificate(n: int, S: list[int], T: list[int]) -> dict[str, object]:
    """Decide the n-divisor property and evaluate the counting walls.

    Returns a witness difference for every i, the lcm-wall check
    lcm(1..n) <= M^(|S||T|) and the binomial wall 4^(n//2) <= (n+1) M^(|S||T|).
    """
    diffs = sorted({s - t for s in S for t in T if t < s})
    witness: dict[int, int] = {}
    for i in range(1, n + 1):
        for d in diffs:
            if d % i == 0:
                witness[i] = d
                break
    covered = len(witness) == n
    M = max(S)
    k = len(S) * len(T)
    L = lcm_upto(n)
    return {
        "covered": covered,
        "missing": [i for i in range(1, n + 1) if i not in witness],
        "witness": witness,
        "lcm_wall_holds": L <= M ** k,
        "binomial_wall_holds": 4 ** (n // 2) <= (n + 1) * M ** k,
        "budget_used": math.log(L) / (k * math.log(M)) if M > 1 else float("inf"),
    }


if __name__ == "__main__":
    print(divisor_property_certificate(10, [17, 21], [1, 3]))

from __future__ import annotations
import itertools
from typing import Optional


def best_two_by_two_cover(n: int, limit: int = 200) -> Optional[tuple[int, tuple[int, int], tuple[int, int]]]:
    """Exhaustive search for the least M admitting positive S={s1,s2}, T={t1,t2}
    (all <= M) whose positive differences divide-cover [n]."""
    targets = range(2, n + 1)
    for M in range(2, limit + 1):
        for s1 in range(1, M):
            for t1, t2 in itertools.combinations(range(1, M), 2):
                diffs = [d for d in (s1 - t1, s1 - t2, M - t1, M - t2) if d > 0]
                if all(any(d % i == 0 for d in diffs) for i in targets):
                    return M, (s1, M), (t1, t2)
    return None


if __name__ == "__main__":
    for n in range(2, 11):
        print(n, best_two_by_two_cover(n))
